        "filetype": "javascriptreact",
        "patterns": [
          "package.json",
          "jsconfig.json"
        ]
      },
      {
        "filetype": "typescript",
        "patterns": [
          "package.json",
          "tsconfig.json"
        ]
      },
      {
        "filetype": "typescriptreact",
        "patterns": [
          "package.json",
          "tsconfig.json"
        ]
      }
