        "category": "TSServer",
        "command": "tsserver.watchBuild"
      },
      {
        "title": "Fix autofixable problems of current document.",
        "category": "TSServer",
        "command": "tsserver.executeAutofix"
      },
      {
        "title": "Choose different typescript version for current project",
        "category": "TSServer",
        "command": "tsserver.chooseVersion"
      }
