[package]
name = "partydeck"
version = "0.8.6"
edition = "2024"

[features]
default = []
download_deps = ["dep:reqwest", "dep:serde_json", "dep:tar", "dep:bzip2", "dep:sevenz-rust2", "dep:sha2"]
download_deps_latest = ["download_deps"]
build_gamescope = []

[dependencies]
dialog = "0.3.0"
eframe = { version = "0.32.1", features = ["x11", "wayland", "accesskit", "default_fonts", "glow"], default-features = false}
egui_extras = { version = "0.32.1", features = ["file", "image"], default-features = false }
evdev = "=0.13.0"
fastrand = "2.3.0"
image = { version = "0.25.8", features = ["jpeg", "png"], default-features = false }
reqwest = { version = "0.12.15", features = ["blocking", "json"] }
rfd = "0.15.3"
serde = "1.0.219"
serde_json = "1.0.140"
x11rb = { version = "0.13.1", default-features = false }
zbus = { version = "5.5.0", features = ["async-io", "blocking-api"], default-features = false }
steamlocate = "2.0.1"
zip = { version = "5.1.1", features = ["deflate", "deflate64"], default-features = false }
pathsearch = "0.2.0"

[build-dependencies]
reqwest = { version = "0.12.15", features = ["blocking", "json"], optional = true }
serde_json = { version = "1.0.140", optional = true }
tar = { version = "0.4", optional = true }
bzip2 = { version = "0.6.1", optional = true }
sevenz-rust2 = { version = "0.20.2", features = ["util"], default-features = false, optional = true }
sha2 = { version = "0.10.9", optional = true}

[workspace]
members = [
    ".",
    "crates/microclaw-core",
    "crates/microclaw-clawhub",
    "crates/microclaw-storage",
    "crates/microclaw-tools",
    "crates/microclaw-channels",
    "crates/microclaw-app",
    "crates/microclaw-observability",
]
resolver = "2"

[profile.release]
strip = true
lto = "thin"
codegen-units = 1

[package]
name = "microclaw"
version = "0.3.5"
edition = "2021"
license = "MIT"
default-run = "microclaw"

[features]
default = []
sqlite-vec = ["microclaw-storage/sqlite-vec"]
journald = ["microclaw-app/journald"]
channel-matrix = ["dep:matrix-sdk"]
full = ["channel-matrix"]

[dependencies]
microclaw-core = { version = "0.1.0", path = "crates/microclaw-core" }
microclaw-clawhub = { version = "0.1.0", path = "crates/microclaw-clawhub" }
microclaw-storage = { version = "0.1.0", path = "crates/microclaw-storage" }
microclaw-tools = { version = "0.1.0", path = "crates/microclaw-tools" }
microclaw-channels = { version = "0.1.0", path = "crates/microclaw-channels" }
microclaw-app = { version = "0.1.0", path = "crates/microclaw-app" }
microclaw-observability = { version = "0.1.0", path = "crates/microclaw-observability" }
teloxide = { version = "0.17", features = ["macros"] }
tokio = { version = "1", features = ["full"] }
tokio-native-tls = "0.3"
native-tls = "0.2"
reqwest = { version = "0.12", features = ["json", "blocking"] }
rusqlite = { version = "0.37", features = ["bundled"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
tracing = "0.1"
tracing-subscriber = { version = "0.3", features = ["env-filter"] }
glob = "0.3"
regex = "1"
thiserror = "2"
anyhow = "1"
async-trait = "0.1"
agent-client-protocol = "0.10.4"
uuid = { version = "1", features = ["v4"] }
chrono = { version = "0.4", features = ["serde"] }
serde_yaml = "0.9"
cron = "0.15"
urlencoding = "2"
base64 = "0.22"
aes = "0.8"
ecb = { version = "0.1", features = ["alloc"] }
chrono-tz = "0.10"
iana-time-zone = "0.1"
zip = "2"
sha2 = "0.10"
md5 = "0.7"
axum = { version = "0.7", features = ["ws"] }
ratatui = { version = "0.30", default-features = false, features = ["crossterm"] }
crossterm = "0.29"
serenity = { version = "0.12", default-features = false, features = ["client", "gateway", "model", "cache", "native_tls_backend"] }
include_dir = "0.7"
async-stream = "0.3"
futures-util = "0.3"
tokio-util = { version = "0.7", features = ["compat"] }
tokio-tungstenite = { version = "0.24", features = ["rustls-tls-webpki-roots"] }
rustls = { version = "0.23", default-features = false, features = ["ring", "std"] }
argon2 = "0.5"
opentelemetry-proto = { version = "0.28", features = ["gen-tonic-messages"] }
opentelemetry-semantic-conventions = { version = "0.30", features = ["semconv_experimental"] }
prost = "0.13"
matrix-sdk = { version = "0.16.1", optional = true, default-features = false, features = ["e2e-encryption", "automatic-room-key-forwarding", "native-tls", "sqlite", "bundled-sqlite"] }
clap = { version = "4.6", features = ["derive"] }
http = "1"
rmcp = { version = "1.7", features = [
    "client",
    "transport-child-process",
    "transport-streamable-http-client-reqwest",
] }
shellexpand = "3.1.2"
qrcode = "0.14"
yaml-edit = "0.2.0"
pulldown-cmark = { version = "0.12", default-features = false }
# Typst typesetting backend for render_pdf: handles layout, CJK, and font
# subsetting (so CJK PDFs stay small instead of embedding a whole ~23MB font).
typst = "0.15"
typst-pdf = "0.15"
typst-layout = "0.15"

[dev-dependencies]
tower = "0.5"

[target.'cfg(windows)'.dependencies]
windows-service = "0.8.1"

