        {
          "command": "junction.addFileToThread",
          "when": "resourceScheme == file",
          "group": "junction"
        }
      ]
    },
    "configuration": {
      "title": "%junction.contributes.configuration.title.junction%",
      "properties": {
        "junction.activeBridge": {
          "type": "string",
          "enum": [
            "openclaw",
            "hermes",
            "souveraine",
            "mimocode",
            "goose",
            "opencode",
            "pi",
            "openhands"
          ],
